const storageKey='reisu-valdymas-demo-v2';let migrationMessage='';
function loadOrders(){try{const saved=localStorage.getItem(storageKey);if(saved){const parsed=JSON.parse(saved);if(Array.isArray(parsed))return parsed.map(o=>({...defaults,...o,history:o.history||[]}));}const legacy=JSON.parse(localStorage.getItem('reisu-valdymas-demo-v1')||'null');if(Array.isArray(legacy)){migrationMessage='Ankstesni užsakymai išsaugoti. Patikrinkite naujus laukus ir technikos suderinimą.';return legacy.map(o=>{const index=['DEMO 101','DEMO 202','DEMO 303','DEMO 404','DEMO 505'].indexOf(o.vehicle);return {...defaults,...o,vehicle:vehicles[index]?.id||'',driver:drivers[['Tomas Kazlauskas','Marius Petrauskas','Andrius Jankauskas','Darius Stankevičius','Lukas Vaitkus'].indexOf(o.driver)]?.name||o.driver||'',reviewed:false,reviewedBy:'',actualKm:null,actualHours:null,history:[]}})}}catch{migrationMessage='Nepavyko perskaityti vietinių duomenų. Įkelti demonstraciniai įrašai.'}return seed()}
let orders=loadOrders(),page='overview',query='',statusFilter='',vehicleFilter='',dateFilter='',weekOffset=0,planDate=today,driverDate=today,selectedDriver=drivers[0].name,planQuery='',planMode='day',lastFocus=null;
const labels={overview:'Apžvalga',orders:'Užsakymai',calendar:'Dispečerio planas',truck:'Transportas',users:'Vairuotojai',driver:'Vairuotojo ekranas'};
icons.driver=icons.users;
const euroSigned=n=>(n>0?'+':'')+euro(n),blank=v=>v===null||v===undefined?'':v;
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(orders));return true}catch{toast('Pakeitimai neišsaugoti naršyklėje. Jie galios tik kol neuždarysite puslapio.');return false}}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4500)}
function badge(s){const cls={'Planuojamas':'planned','Vykdomas':'active-trip','Atvyko į objektą':'arrived','Dirba objekte':'working','Užbaigtas':'done','Atšauktas':'cancelled'};return `<span class="badge ${cls[s]||'planned'}">${esc(s)}</span>`}
function head(title,sub,extra='',newButton=true){return `<div class="page-head"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${extra}${newButton?`<button class="btn primary" data-new>${svg('plus')} Naujas užsakymas</button>`:''}</div></div>`}
function dateLabel(d){return new Date(d+'T12:00:00').toLocaleDateString('lt-LT',{month:'long',day:'numeric'})}
function current(v){return orders.find(o=>o.vehicle===v&&o.date===today&&['Vykdomas','Atvyko į objektą','Dirba objekte'].includes(o.status))}
const total=list=>list.filter(o=>o.status!=='Atšauktas').reduce((s,o)=>s+Model.price(o),0);
function stats(){const day=orders.filter(o=>o.date===today&&o.status!=='Atšauktas');return `<div class="stats">${[['Šiandienos užsakymai',day.length,'Visi dienos darbai','orders'],['Laukia priskyrimo',day.filter(o=>!o.vehicle&&Model.open(o)).length,'Transportas ir vairuotojas','clock'],['Šiuo metu vykdomi',day.filter(o=>['Vykdomas','Atvyko į objektą','Dirba objekte'].includes(o.status)).length,'Pagal pažymėtas būsenas','truck'],['Planuojama dienos vertė',euro(day.reduce((s,o)=>s+Model.planned(o),0)),'Planas · be PVM','euro']].map(x=>`<article class="stat"><div class="stat-top"><span>${x[0]}</span><div class="stat-icon">${svg(x[3])}</div></div><div class="stat-number">${x[1]}</div><div class="stat-note">${x[2]}</div></article>`).join('')}</div>`}
function table(list,compact=false){return `<div class="table-wrap"><table><thead><tr><th>UŽSAKYMAS</th><th>MARŠRUTAS / KROVINYS</th><th>TRANSPORTAS / VAIRUOTOJAS</th>${compact?'':'<th>DATA / LAIKAS</th><th>PLANAS / FAKTAS</th>'}<th>BŪSENA</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><button class="row-button" data-detail="${esc(o.id)}">${esc(o.id)}</button><div class="small">${compact?o.start:esc(o.client)}</div></td><td><div class="route">${esc(o.from)} <span class="arrow">→</span> ${esc(o.to)}</div><div class="small">${esc(o.cargo||o.service)}</div></td><td>${o.vehicle?esc(o.vehicle):'<span class="unassigned">Nepriskirtas</span>'}<div class="small">${esc(o.driver||'Reikia vairuotojo')}${o.vehicle&&!o.reviewed?' · reikia suderinimo':''}</div></td>${compact?'':`<td>${esc(o.date)}<div class="small">${esc(o.start)}–${esc(o.end)}</div></td><td><b>${euro(Model.planned(o))}</b><div class="small">Faktas: ${Model.actual(o)===null?'—':euro(Model.actual(o))}</div></td>`}<td>${badge(o.status)}</td><td><button class="iconbutton" aria-label="Atidaryti ${esc(o.id)}" data-detail="${esc(o.id)}">›</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Užsakymų nėra. Pakeiskite filtrus arba sukurkite naują užsakymą.</td></tr>'}</tbody></table></div>`}
function overview(){const day=orders.filter(o=>o.date===today&&o.status!=='Atšauktas').sort((a,b)=>a.start.localeCompare(b.start));return head('Reisų apžvalga',`${dateLabel(today)} · Pervežimas, kėlimas ir montavimas vienoje vietoje`)+stats()+`<div class="grid-main"><div><div class="panel"><div class="panel-head"><div><h3>Šiandienos reisai</h3><p class="subtitle">Nuo užsakymo iki atlikto darbo</p></div><button class="textbutton" data-page="calendar">Dispečerio planas →</button></div>${table(day,true)}</div><div class="panel"><div class="panel-head"><h3>Artimiausi užsakymai</h3><button class="textbutton" data-page="orders">Visi užsakymai →</button></div>${table(orders.filter(o=>o.date>today&&o.status!=='Atšauktas').sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).slice(0,3))}</div></div><aside><div class="panel"><div class="panel-head"><h3>Transporto būsena</h3><span class="small">DEMO</span></div>${vehicles.map(v=>{const o=current(v.id);return `<div class="fleet-mini"><div class="truck-icon">${svg('truck')}</div><div class="fleet-info"><b>${v.id}</b><div class="small">${v.name}</div></div><span class="fleet-status ${o?'busy':''}">${o?o.status==='Vykdomas'?'Reise':'Objekte':'Laisvas'}</span></div>`}).join('')}</div><div class="notice"><b>Pristatymo scenarijus</b>1. Užregistruokite krovinį.<br>2. Plane priskirkite techniką.<br>3. Vairuotojo ekrane vykdykite reisą.<br>4. Užbaikite įvesdami faktą.</div><p class="small demo-disclaimer">Visi automobiliai, techniniai parametrai, tarifai, vairuotojai, klientai ir adresai yra demonstraciniai. Duomenys skirti tik prototipo demonstravimui.</p></aside></div>`}
function filtered(){return orders.filter(o=>(!statusFilter||o.status===statusFilter)&&(!vehicleFilter||(vehicleFilter==='unassigned'?!o.vehicle:o.vehicle===vehicleFilter))&&(!dateFilter||o.date===dateFilter)&&(!query||[o.id,o.client,o.from,o.to,o.vehicle,o.driver,o.cargo,o.fromAddress,o.toAddress].join(' ').toLocaleLowerCase('lt').includes(query.toLocaleLowerCase('lt')))).sort((a,b)=>b.date.localeCompare(a.date)||a.start.localeCompare(b.start))}
function orderResults(){const list=filtered();return table(list)+`<div class="table-bottom"><span>Užsakymų: ${list.length}</span><span>Planas: <b>${euro(list.filter(o=>o.status!=='Atšauktas').reduce((s,o)=>s+Model.planned(o),0))}</b></span></div>`}
function orderPage(){return head('Užsakymai','Kroviniai, darbų vietos, technika ir finansinis rezultatas.',`<button class="btn secondary" id="export">${svg('download')} Eksportuoti</button>`)+`<div class="panel"><div class="toolbar"><div class="search">${svg('search')}<input id="search" placeholder="Užsakymas, klientas, krovinys, adresas…" aria-label="Ieškoti užsakymų" value="${esc(query)}"></div><select id="statusFilter" aria-label="Būsena"><option value="">Visos būsenos</option>${Model.statuses.map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select><select id="vehicleFilter" aria-label="Transportas"><option value="">Visas transportas</option><option value="unassigned" ${vehicleFilter==='unassigned'?'selected':''}>Nepriskirti</option>${vehicles.map(v=>`<option ${v.id===vehicleFilter?'selected':''}>${v.id}</option>`).join('')}</select><input type="date" id="dateFilter" value="${dateFilter}" aria-label="Data"><button class="textbutton" id="clearFilters">Išvalyti</button></div><div id="orderResults">${orderResults()}</div></div>`}
function plan(){const unassigned=orders.filter(o=>o.date===planDate&&!o.vehicle&&Model.open(o));return head('Dispečerio planas','Valandinis užimtumas, nepriskirti užsakymai ir technikos parinkimas.')+`<div class="panel"><div class="panel-head"><div class="segmented"><button id="dayMode" class="${planMode==='day'?'selected':''}">Dienos planas</button><button id="weekMode" class="${planMode==='week'?'selected':''}">Savaitė</button></div><div class="week-nav"><button class="iconbutton" id="prevPlan" aria-label="Ankstesnė diena arba savaitė">‹</button><input type="date" id="planDate" value="${planDate}" aria-label="Plano data"><button class="iconbutton" id="nextPlan" aria-label="Kita diena arba savaitė">›</button><button class="btn secondary" id="todayPlan">Šiandien</button></div></div><div class="toolbar"><div class="search">${svg('search')}<input id="planSearch" value="${esc(planQuery)}" placeholder="Ieškoti transporto…" aria-label="Ieškoti transporto plane"></div><span class="small">Paspauskite reisą, kad jį peržiūrėtumėte</span></div><div id="planBoard">${planMode==='day'?dayBoard():weekBoard()}</div></div><div class="panel"><div class="panel-head"><div><h3>Laukia priskyrimo <span class="count">${unassigned.length}</span></h3><p class="subtitle">${planDate} · Parinkite techniką pagal krovinį ir laisvą laiką</p></div></div><div class="unassigned-grid">${unassigned.map(o=>`<div class="unassigned-card"><div class="card-title"><button class="row-button" data-detail="${esc(o.id)}">${esc(o.id)}</button><span>${o.start}–${o.end}</span></div><h3>${esc(o.from)} → ${esc(o.to)}</h3><p>${esc(o.cargo||o.cargoType)}</p><div class="small">${o.weight} t · ${o.length} × ${o.width} × ${o.height} m${Model.needsCrane(o)?' · reikalingas kranas':''}</div><button class="btn primary" data-assign="${esc(o.id)}">Parinkti transportą</button></div>`).join('')||'<div class="empty">Visi šios dienos užsakymai priskirti.</div>'}</div></div><p class="small">Transporto vieta nustatoma pagal užsakymo maršrutą ir būseną. GPS sekimas neprijungtas.</p>`}
function filteredVehicles(){return vehicles.filter(v=>(v.id+' '+v.name).toLowerCase().includes(planQuery.toLowerCase()))}
function dayBoard(){const list=orders.filter(o=>o.date===planDate&&o.vehicle&&o.status!=='Atšauktas'),min=Math.min(6,...list.map(o=>Math.floor(Model.minutes(o.start)/60))),max=Math.max(22,...list.map(o=>Math.ceil(Model.minutes(o.end)/60))),span=(max-min)*60,hours=Array.from({length:max-min},(_,i)=>i+min);return `<div class="timeline-scroll"><div class="timeline"><div class="timeline-header"><div>TRANSPORTAS</div><div class="hour-labels" style="--hours:${hours.length}">${hours.map(h=>`<span>${String(h).padStart(2,'0')}:00</span>`).join('')}</div></div>${filteredVehicles().map(v=>{const trips=list.filter(o=>o.vehicle===v.id).sort((a,b)=>a.start.localeCompare(b.start));let laneEnds=[];const layout=trips.map(o=>{let lane=laneEnds.findIndex(end=>end<=o.start);if(lane<0)lane=laneEnds.length;laneEnds[lane]=o.end;return {o,lane}});return `<div class="timeline-row"><div class="timeline-label"><b>${v.id}</b><span>${v.name}</span><small>${trips.length?'Po paskutinio reiso: '+trips.reduce((m,o)=>o.end>m?o.end:m,'00:00'):'Laisvas visą dieną'}</small></div><div class="timeline-track" style="--hours:${hours.length};height:${Math.max(92,laneEnds.length*68+16)}px">${layout.map(({o,lane})=>`<button class="time-event ${o.status==='Užbaigtas'?'complete':o.status==='Vykdomas'?'transit':''}" style="left:${(Model.minutes(o.start)-min*60)/span*100}%;width:${(Model.minutes(o.end)-Model.minutes(o.start))/span*100}%;top:${8+lane*68}px" data-detail="${esc(o.id)}" title="${esc(o.id+' · '+o.from+' → '+o.to+' · '+o.start+'–'+o.end)}"><b>${o.start}–${o.end} · ${esc(o.id)}</b><span>${esc(o.from)} → ${esc(o.to)}</span><small>${esc(o.driver.split(' (')[0])}</small></button>`).join('')}</div></div>`}).join('')}</div></div>`}
function weekBoard(){const d=new Date(planDate+'T12:00:00');d.setDate(d.getDate()-(d.getDay()+6)%7);const days=Array.from({length:7},(_,i)=>Model.addDays(Model.date(d),i));return `<div class="table-wrap"><table class="calendar"><thead><tr><th>TRANSPORTAS</th>${days.map((day,i)=>`<th class="${day===today?'today':''}">${['PIRM','ANTR','TREČ','KETV','PENK','ŠEŠT','SEKM'][i]}<span class="daynum">${day.slice(-2)}</span></th>`).join('')}</tr></thead><tbody>${filteredVehicles().map(v=>`<tr><td><b>${v.id}</b><div class="small">${v.name}</div></td>${days.map(day=>`<td class="${day===today?'today':''}">${orders.filter(o=>o.vehicle===v.id&&o.date===day&&o.status!=='Atšauktas').sort((a,b)=>a.start.localeCompare(b.start)).map(o=>`<button class="event ${o.status==='Vykdomas'?'transit':o.status==='Užbaigtas'?'complete':''}" data-detail="${esc(o.id)}"><strong>${o.start}–${o.end}</strong>${esc(o.from)} → ${esc(o.to)}<br>${esc(o.id)}</button>`).join('')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function resources(type){const truck=type==='truck';return head(truck?'Transportas':'Vairuotojai',truck?'Demonstracinės technikos kortelės. Tikras parkas ir parametrai turi būti suderinti su klientu.':'Demonstraciniai kontaktai ir priskirti reisai.')+`<div class="cards">${(truck?vehicles:drivers).map((v,i)=>{const list=orders.filter(o=>truck?o.vehicle===v.id:o.driver===v.name),running=list.find(o=>o.date===today&&!['Planuojamas','Užbaigtas','Atšauktas'].includes(o.status));return `<article class="resource-card"><div class="resource-top"><div class="truck-icon">${svg(type)}</div>${running?badge(running.status):'<span class="badge done">Laisvas</span>'}</div><h3>${esc(truck?v.id:v.name)}</h3><p class="subtitle">${esc(truck?v.name:v.phone)}</p><div class="resource-data">${truck?(v.kind==='equipment'?'<div class="full"><label>TIPAS</label>Pavyzdinė statybinė technika</div>':`<div><label>KROVINIO MASĖ</label>Iki ${v.payload} t</div><div><label>PLATFORMA</label>${v.length} × ${v.width} m</div><div><label>MAKS. KĖLIMO GALIA</label>${v.crane?v.lift+' t':'Krano nėra'}</div><div><label>MAKS. STRĖLĖS SIEKIS</label>${v.crane?v.reach+' m':'—'}</div><div><label>PRIEKABOS GALIMYBĖ</label>${v.trailer?'Taip':'Ne'}</div><div><label>TARIFAI (DEMO)</label>${euro(v.rate)}/km · ${euro(v.hourRate)}/val.</div>`):`<div><label>ŠIANDIENOS REISAI</label>${list.filter(o=>o.date===today&&o.status!=='Atšauktas').length}</div><div><label>PLANUOJAMI REISAI</label>${list.filter(o=>o.status==='Planuojamas').length}</div>`}<div class="full"><label>DABARTINIS REISAS</label>${running?esc(running.from)+' → '+esc(running.to):'Aktyvaus reiso nėra'}</div></div><button class="btn secondary" data-resource="${i}" data-type="${type}">Peržiūrėti užsakymus →</button>${truck?'':`<button class="btn primary driver-open" data-driver="${esc(v.name)}">Atidaryti vairuotojo ekraną</button>`}</article>`}).join('')}</div>${truck?'<div class="notice"><b>Parametrai skirti demonstracijai</b>Maksimali kėlimo galia ir maksimalus strėlės siekis nėra vienu metu galiojanti keliamosios galios garantija. Kėlimą konkrečiu atstumu ir darbų sąlygas turi patikrinti atsakingas specialistas pagal konkrečios technikos dokumentaciją.</div>':''}`}
function actionLabel(o){return {'Planuojamas':'Išvykau','Vykdomas':'Atvykau į objektą','Atvyko į objektą':Model.next(o)==='Dirba objekte'?'Pradėjau darbą':'Baigiau reisą','Dirba objekte':'Baigiau darbą'}[o.status]||''}
function driverPage(){const list=orders.filter(o=>o.driver===selectedDriver&&o.date===driverDate&&o.status!=='Atšauktas').sort((a,b)=>a.start.localeCompare(b.start));return head('Mano reisai','Paprastas vairuotojo ekranas darbui telefonu.','',false)+`<div class="driver-toolbar"><label>Vairuotojas (demo perjungimas)<select id="driverSelect">${drivers.map(d=>`<option ${d.name===selectedDriver?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label>Data<input type="date" id="driverDate" value="${driverDate}"></label><span class="small">Tai vaizdo perjungimas, ne prisijungimas ar prieigos ribojimas.</span></div><div class="driver-list">${list.map(o=>`<article class="driver-card"><div class="driver-card-head"><div><b>${o.start}–${o.end}</b><span>${esc(o.id)} · ${esc(o.vehicle)}</span></div>${badge(o.status)}</div><div class="driver-card-body"><h2>${esc(o.from)} → ${esc(o.to)}</h2><p class="subtitle">${esc(o.cargo||o.service)} · ${o.weight} t · ${o.quantity} vnt.</p><div class="stop"><i>A</i><div><label>PAKROVIMAS</label><b>${esc(o.fromAddress||o.from)}</b><span>${esc(o.pickupContact||'Kontaktas nenurodytas')}</span>${phoneLink(o.pickupPhone)}</div></div><div class="stop"><i>B</i><div><label>OBJEKTAS · ATVYKTI ${esc(o.arrival||'pagal susitarimą')}</label><b>${esc(o.toAddress||o.to)}</b><span>${esc(o.siteContact||'Kontaktas nenurodytas')}</span>${phoneLink(o.sitePhone)}</div></div>${o.access?`<div class="access-note"><b>Privažiavimas</b>${esc(o.access)}</div>`:''}<div class="work-tags">${[o.loading?'Pakrovimas':null,o.unloading?'Iškrovimas':null,o.installation?'Montavimas':null].filter(Boolean).map(x=>`<span>${x}</span>`).join('')}</div>${o.notes?`<p class="detail-note">${esc(o.notes)}</p>`:''}${Model.next(o)?`<button class="btn primary driver-action" data-progress="${esc(o.id)}">${svg('check')} ${actionLabel(o)}</button>`:`<div class="driver-finished">${svg('check')} Užbaigta · Faktas: ${Model.actual(o)===null?'dar neįvestas':euro(Model.actual(o))}</div>`}<button class="textbutton" data-detail="${esc(o.id)}">Visa užsakymo informacija</button></div></article>`).join('')||'<div class="panel empty">Šiai dienai reisų nepriskirta.</div>'}</div>`}
function phoneLink(phone){return phone?`<a class="phone-link" href="tel:${esc(phone.replace(/[^+0-9]/g,''))}">${esc(phone)}</a>`:''}
function render(){document.getElementById('crumb').textContent=labels[page];document.getElementById('nav').innerHTML=Object.entries(labels).map(([k,v])=>`<button class="nav-item ${k===page?'active':''}" data-page="${k}">${svg(k)}${v}</button>`).join('');document.getElementById('content').innerHTML=page==='overview'?overview():page==='orders'?orderPage():page==='calendar'?plan():page==='driver'?driverPage():resources(page);bind()}
function navigate(p){page=p;query='';statusFilter='';vehicleFilter='';dateFilter='';render()}
function bindCommon(root=document){root.querySelectorAll('[data-detail]').forEach(e=>e.onclick=()=>detail(e.dataset.detail));root.querySelectorAll('[data-assign]').forEach(e=>e.onclick=()=>assign(e.dataset.assign));root.querySelectorAll('[data-progress]').forEach(e=>e.onclick=()=>progress(e.dataset.progress));}
function bind(){document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>navigate(e.dataset.page));document.querySelectorAll('[data-new]').forEach(e=>e.onclick=()=>edit());bindCommon();document.querySelectorAll('[data-resource]').forEach(e=>e.onclick=()=>{page='orders';query=e.dataset.type==='users'?drivers[Number(e.dataset.resource)].name:'';vehicleFilter=e.dataset.type==='truck'?vehicles[Number(e.dataset.resource)].id:'';dateFilter='';statusFilter='';render()});document.querySelectorAll('[data-driver]').forEach(e=>e.onclick=()=>{selectedDriver=e.dataset.driver;page='driver';render()});if(page==='orders'){document.getElementById('search').oninput=e=>{query=e.target.value;refreshResults()};['status','vehicle','date'].forEach(k=>document.getElementById(k+'Filter').onchange=e=>{if(k==='status')statusFilter=e.target.value;if(k==='vehicle')vehicleFilter=e.target.value;if(k==='date')dateFilter=e.target.value;refreshResults()});document.getElementById('clearFilters').onclick=()=>navigate('orders');document.getElementById('export').onclick=exportCsv}if(page==='calendar'){document.getElementById('prevPlan').onclick=()=>{planDate=Model.addDays(planDate,planMode==='day'?-1:-7);render()};document.getElementById('nextPlan').onclick=()=>{planDate=Model.addDays(planDate,planMode==='day'?1:7);render()};document.getElementById('todayPlan').onclick=()=>{planDate=today;render()};document.getElementById('planDate').onchange=e=>{if(e.target.value){planDate=e.target.value;render()}};document.getElementById('dayMode').onclick=()=>{planMode='day';render()};document.getElementById('weekMode').onclick=()=>{planMode='week';render()};document.getElementById('planSearch').oninput=e=>{planQuery=e.target.value;document.getElementById('planBoard').innerHTML=planMode==='day'?dayBoard():weekBoard();bindCommon(document.getElementById('planBoard'))}}if(page==='driver'){document.getElementById('driverSelect').onchange=e=>{selectedDriver=e.target.value;render()};document.getElementById('driverDate').onchange=e=>{if(e.target.value){driverDate=e.target.value;render()}}}}
function refreshResults(){document.getElementById('orderResults').innerHTML=orderResults();bindCommon(document.getElementById('orderResults'))}
function openDrawer(title,content,eyebrow='UŽSAKYMAS'){if(document.getElementById('overlay').hidden)lastFocus=document.activeElement;document.getElementById('drawerTitle').textContent=title;document.getElementById('drawerEyebrow').textContent=eyebrow;document.getElementById('drawerContent').innerHTML=content;document.getElementById('overlay').hidden=false;document.body.style.overflow='hidden';document.querySelector('.drawer').scrollTop=0;document.getElementById('close').focus()}
function closeDrawer(){document.getElementById('overlay').hidden=true;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
function priceComparison(o){const fact=Model.actual(o);return `<div class="price-comparison"><div class="compare-row compare-head"><span></span><b>Planas</b><b>Faktas</b></div><div class="compare-row"><span>Kilometrai</span><b>${o.km} km</b><b>${Model.present(o.actualKm)?o.actualKm+' km':'—'}</b></div><div class="compare-row"><span>Darbo laikas</span><b>${o.hours} val.</b><b>${Model.present(o.actualHours)?o.actualHours+' val.':'—'}</b></div><div class="compare-row"><span>Pervežimas · ${euro(o.rate)}/km</span><b>${euro(o.km*o.rate)}</b><b>${Model.present(o.actualKm)?euro(o.actualKm*o.rate):'—'}</b></div><div class="compare-row"><span>Darbas · ${euro(o.hourRate)}/val.</span><b>${euro(o.hours*o.hourRate)}</b><b>${Model.present(o.actualHours)?euro(o.actualHours*o.hourRate):'—'}</b></div><div class="compare-row compare-total"><span>Kaina be PVM</span><b>${euro(Model.planned(o))}</b><b>${fact===null?'—':euro(fact)}</b></div>${fact!==null?`<div class="price-diff">Pokytis nuo plano: <b>${euroSigned(Model.round(fact-Model.planned(o)))}</b></div>`:'<p class="small">Galutinė kaina bus apskaičiuota įvedus faktinius kilometrus ir valandas.</p>'}</div>`}
function infoPairs(items){return `<div class="detail-grid">${items.map(([label,value])=>`<div><label>${label}</label>${esc(value||'—')}</div>`).join('')}</div>`}
function detail(id){const o=orders.find(x=>x.id===id);if(!o)return;openDrawer(o.id,`<div class="detail-body">${badge(o.status)}<div class="detail-route">${esc(o.from)} <span class="arrow">→</span> ${esc(o.to)}</div><p class="subtitle">${esc(o.service)} · ${esc(o.client)}</p>${infoPairs([['DATA / LAIKAS',o.date+' · '+o.start+'–'+o.end],['ATVYKIMAS Į OBJEKTĄ',o.arrival],['TRANSPORTAS',o.vehicle||'Nepriskirtas'],['VAIRUOTOJAS',o.driver||'Nepriskirtas'],['KLIENTO TELEFONAS',o.phone],['KLIENTO EL. PAŠTAS',o.email]])}<div class="section-label">KROVINYS IR DARBAI</div><div class="detail-note"><b>${esc(o.cargo||o.cargoType)}</b><br>${o.quantity} vnt. · Bendras svoris ${o.weight} t<br>${o.length} × ${o.width} × ${o.height} m${Model.needsCrane(o)?`<br>Sunkiausias keliamas vienetas: ${o.liftWeight} t · Reikiamas siekis: ${o.reach} m`:''}</div><div class="work-tags">${[[o.loading,'Pakrovimas'],[o.unloading,'Iškrovimas'],[o.installation,'Montavimas'],[o.trailerRequired,'Reikia priekabos']].filter(x=>x[0]).map(x=>`<span>${x[1]}</span>`).join('')}</div><div class="section-label">DARBŲ VIETOS</div><div class="stop"><i>A</i><div><label>PAKROVIMAS</label><b>${esc(o.fromAddress||o.from)}</b><span>${esc(o.pickupContact)}</span>${phoneLink(o.pickupPhone)}</div></div><div class="stop"><i>B</i><div><label>IŠKROVIMAS / OBJEKTAS</label><b>${esc(o.toAddress||o.to)}</b><span>${esc(o.siteContact)}</span>${phoneLink(o.sitePhone)}</div></div>${o.access?`<div class="access-note"><b>Privažiavimas ir sąlygos</b>${esc(o.access)}</div>`:''}<div class="section-label">PLANAS IR FAKTAS</div>${priceComparison(o)}<div class="review-status ${o.reviewed?'verified':''}">${o.reviewed?'Techninis suderinimas patvirtintas: '+esc(o.reviewedBy):'Techninis suderinimas dar nepatvirtintas'}</div>${o.notes?`<div class="detail-note">${esc(o.notes)}</div>`:''}<div class="step-actions">${Model.next(o)?`<button class="btn primary" id="advance">${actionLabel(o)}</button>`:''}<button class="btn secondary" id="editOrder">Redaguoti</button>${o.status==='Planuojamas'?'<button class="btn secondary" id="assignOrder">Parinkti transportą</button>':''}${Model.open(o)?'<button class="btn danger" id="cancelOrder">Atšaukti</button>':''}</div>${o.history.length?`<div class="section-label">VYKDYMO ISTORIJA</div><div class="history">${o.history.map(h=>`<div><i></i><span><b>${esc(h.status)}</b><small>${esc(new Date(h.at).toLocaleString('lt-LT'))} · ${esc(h.by)}</small></span></div>`).join('')}</div>`:''}</div>`);document.getElementById('editOrder').onclick=()=>edit(id);if(Model.next(o))document.getElementById('advance').onclick=()=>progress(id);if(o.status==='Planuojamas')document.getElementById('assignOrder').onclick=()=>assign(id);if(Model.open(o))document.getElementById('cancelOrder').onclick=()=>{if(confirm('Atšaukti užsakymą '+id+'?')){o.status='Atšauktas';o.history.push({status:'Atšauktas',at:new Date().toISOString(),by:'Dispečeris'});persist();render();detail(id);toast('Užsakymas atšauktas')}}}
function field(label,name,value,type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(blank(value))}" ${extra}></label>`}
function selectField(label,name,value,items,required=true){return `<label class="field">${label}<select name="${name}" ${required?'required':''}>${items.map(x=>`<option value="${esc(x.value??x)}" ${(x.value??x)===value?'selected':''}>${esc(x.label??x)}</option>`).join('')}</select></label>`}
function check(label,name,value){return `<label class="check-label"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`}
const numericFields=['km','rate','hours','hourRate','weight','length','width','height','quantity','liftWeight','reach'],boolFields=['loading','unloading','installation','trailerRequired','reviewed'];
function formData(form){const data=Object.fromEntries(new FormData(form));for(const k in data)if(typeof data[k]==='string')data[k]=data[k].trim();for(const k of numericFields)data[k]=Number(data[k]||0);for(const k of ['actualKm','actualHours'])data[k]=data[k]===''||data[k]===undefined?null:Number(data[k]);for(const k of boolFields)data[k]=form.elements[k]?.checked||false;return data}
function formError(text,id='formError'){const e=document.getElementById(id);e.innerHTML=`<div class="error">${esc(text)}</div>`;e.scrollIntoView({block:'nearest'})}
function edit(id){const old=orders.find(x=>x.id===id),o=old||{...defaults,id:'RV-'+(Math.max(1040,...orders.map(x=>Number(x.id.replace(/^RV-/,''))||0))+1),date:page==='calendar'?planDate:today,history:[]};const number=(label,name,extra='')=>field(label,name,o[name],'number','min="0" step="0.01" '+extra);openDrawer(old?'Redaguoti '+id:'Naujas užsakymas',`<form id="orderForm"><div class="form-body"><div class="form-section"><div class="section-label">01 · UŽSAKYMAS IR LAIKAS</div><div class="form-grid">${field('Užsakymo numeris *','id',o.id,'text','required maxlength="30"')}${selectField('Būsena','status',o.status,Model.statuses)}${field('Data *','date',o.date,'date','required')}${selectField('Paslauga','service',o.service,['Krovinių pervežimas','Pervežimas su fiskaru','Montavimo darbai','Statybinės technikos nuoma'])}${field('Transporto užimtumo pradžia *','start',o.start,'time','required')}${field('Transporto užimtumo pabaiga *','end',o.end,'time','required')}${field('Atvykimas į objektą','arrival',o.arrival,'time')}</div></div><div class="form-section"><div class="section-label">02 · KLIENTAS</div><div class="form-grid">${field('Klientas / įmonė *','client',o.client,'text','required maxlength="120"')}${field('Telefonas','phone',o.phone,'tel','maxlength="30"')}${field('El. paštas','email',o.email,'email','maxlength="120"')}</div></div><div class="form-section"><div class="section-label">03 · KROVINYS IR DARBŲ POREIKIS</div><div class="form-grid">${selectField('Krovinio tipas','cargoType',o.cargoType,['Statybinės medžiagos','Moduliniai nameliai / konteineriai','Metalo konstrukcijos','Įrengimai / staklės','Mediena','Kita'])}${field('Krovinio aprašymas','cargo',o.cargo,'text','maxlength="200"')}${number('Bendras krovinio svoris, t','weight')}${field('Vienetų skaičius','quantity',o.quantity,'number','required min="1" step="1"')}${number('Ilgis, m (ilgiausio vieneto)','length')}${number('Plotis, m (plačiausio vieneto)','width')}${number('Aukštis, m','height')}${number('Sunkiausias keliamas vienetas, t','liftWeight')}${number('Reikalingas krano siekis, m','reach')}</div><div class="checks">${check('Pakrovimas kranu','loading',o.loading)}${check('Iškrovimas kranu','unloading',o.unloading)}${check('Montavimo darbai','installation',o.installation)}${check('Reikia priekabos galimybės','trailerRequired',o.trailerRequired)}</div></div><div class="form-section"><div class="section-label">04 · PAKROVIMO VIETA</div><div class="form-grid">${field('Miestas / vietovė *','from',o.from,'text','required maxlength="120"')}${field('Tikslus pakrovimo adresas','fromAddress',o.fromAddress,'text','maxlength="200"')}${field('Kontaktinis asmuo','pickupContact',o.pickupContact,'text','maxlength="100"')}${field('Kontaktinis telefonas','pickupPhone',o.pickupPhone,'tel','maxlength="30"')}</div></div><div class="form-section"><div class="section-label">05 · IŠKROVIMAS / OBJEKTAS</div><div class="form-grid">${field('Miestas / vietovė *','to',o.to,'text','required maxlength="120"')}${field('Tikslus objekto adresas','toAddress',o.toAddress,'text','maxlength="200"')}${field('Kontaktinis asmuo objekte','siteContact',o.siteContact,'text','maxlength="100"')}${field('Kontaktinis telefonas','sitePhone',o.sitePhone,'tel','maxlength="30"')}<label class="field full">Privažiavimas, darbo vieta ir sąlygos<textarea name="access" rows="2" maxlength="1000">${esc(o.access)}</textarea></label></div></div><div class="form-section"><div class="section-label">06 · TRANSPORTAS IR SUDERINIMAS</div><div class="form-grid">${selectField('Transportas','vehicle',o.vehicle,[{value:'',label:'Nepriskirtas'},...vehicles.map(v=>({value:v.id,label:v.id+' · '+v.name}))],false)}${selectField('Vairuotojas','driver',o.driver,[{value:'',label:'Nepriskirtas'},...drivers.map(d=>d.name)],false)}</div><div id="suitabilityPreview"></div><p class="small">Parinkimas preliminarus. Patikrinkite keliamosios galios diagramą konkrečiu siekiu, krovinio aukštį, išdėstymą ir objekto sąlygas.</p>${check('Atsakingas asmuo patvirtino technikos tinkamumą šiam darbui','reviewed',o.reviewed)}${field('Suderinęs asmuo','reviewedBy',o.reviewedBy,'text','maxlength="100"')}<p class="small">Jeigu technika dar neparinkta, abu priskyrimo laukus palikite tuščius.</p></div><div class="form-section"><div class="section-label">07 · PLANAS, FAKTAS IR KAINA</div><div class="form-grid">${number('Planuojami kilometrai','km','required')}${number('Kilometro tarifas, €','rate','required')}${number('Planuojamos darbo valandos','hours','required max="24"')}${number('Krano / technikos tarifas, €/val.','hourRate','required')}${number('Faktiniai kilometrai','actualKm')}${number('Faktinės darbo valandos','actualHours','max="24"')}</div><button type="button" class="textbutton tariff-button" id="useRates">Naudoti pasirinktos technikos demo tarifus</button><div id="pricePreview"></div><p class="small">Faktą įveskite po darbo. Nulis reiškia, kad kilometrų ar darbo valandų nebuvo. Kainos be PVM.</p></div><label class="field">Papildomos pastabos<textarea name="notes" rows="3" maxlength="1000">${esc(o.notes)}</textarea></label><div id="formError" role="alert"></div></div><div class="form-actions"><button type="button" class="btn secondary" id="discard">Uždaryti</button><button type="submit" class="btn primary">Išsaugoti užsakymą</button></div></form>`);
const form=document.getElementById('orderForm');const preview=()=>{const d=formData(form);document.getElementById('pricePreview').innerHTML=priceComparison(d);const v=vehicles.find(v=>v.id===d.vehicle),reasons=v?Model.suitability(d,v):[],conflict=Model.conflict({...d,id:old?.id||d.id},orders.filter(x=>x!==old));document.getElementById('suitabilityPreview').innerHTML=!v?'<div class="review-status">Užsakymas bus rodomas nepriskirtų sąraše.</div>':`<div class="review-status ${!reasons.length&&!conflict?'verified':''}">${reasons.length?esc(reasons.join('. ')):conflict?'Užimtumo konfliktas su '+esc(conflict.id):'Pagal įvestus parametrus ir laiką kliūčių nerasta. Reikalingas techninis patvirtinimas.'}</div>`};const technicalFields=['vehicle','service','weight','length','width','height','quantity','liftWeight','reach','loading','unloading','installation','trailerRequired','cargo','cargoType','access'];form.oninput=e=>{if(technicalFields.includes(e.target.name)){form.elements.reviewed.checked=false;form.elements.reviewedBy.value=''}preview()};form.onchange=e=>{if(technicalFields.includes(e.target.name)){form.elements.reviewed.checked=false;form.elements.reviewedBy.value=''}preview()};preview();document.getElementById('useRates').onclick=()=>{const v=vehicles.find(v=>v.id===form.elements.vehicle.value);if(!v){toast('Pirmiausia pasirinkite techniką');return}form.elements.rate.value=v.rate;form.elements.hourRate.value=v.hourRate;preview()};document.getElementById('discard').onclick=closeDrawer;form.onsubmit=e=>{e.preventDefault();const data={...defaults,...formData(form),history:[...(old?.history||[])]};const error=Model.validate(data,orders.filter(x=>x!==old),vehicles);if(error){formError(error);return}if(old&&old.status!==data.status)data.history.push({status:data.status,at:new Date().toISOString(),by:'Dispečeris (redagavimas)'});if(!data.vehicle){data.reviewed=false;data.reviewedBy=''}if(old)orders[orders.indexOf(old)]=data;else orders.push(data);const saved=persist();closeDrawer();render();if(saved)toast(old?'Užsakymas atnaujintas':'Užsakymas sukurtas')};}
function assign(id){const o=orders.find(x=>x.id===id);let candidate=o.vehicle,chosenDriver=o.driver||drivers.find(d=>!Model.conflict({...o,vehicle:'',driver:d.name},orders))?.name||drivers[0].name,onlyFit=true;function candidates(){return vehicles.map(v=>{const reasons=Model.suitability(o,v),c=Model.conflict({...o,vehicle:v.id,driver:chosenDriver},orders);return {v,reasons,c}})}
function content(){const candidatesList=candidates().filter(x=>!onlyFit||(!x.reasons.length&&!x.c));return `<div class="detail-body"><div class="detail-note"><b>${esc(o.from)} → ${esc(o.to)}</b><br>${o.date} · ${o.start}–${o.end}<br>${esc(o.cargo||o.cargoType)} · ${o.weight} t · ${o.length} × ${o.width} × ${o.height} m</div><div class="assign-driver">${selectField('Vairuotojas','assignDriver',chosenDriver,drivers.map(d=>d.name))}</div>${check('Rodyti tik laisvą ir preliminariai tinkamą techniką','onlyFit',onlyFit)}<div class="candidate-list">${candidatesList.map(({v,reasons,c})=>`<button type="button" class="candidate ${candidate===v.id?'chosen':''}" data-candidate="${v.id}" ${reasons.length||c?'disabled':''}><div><b>${v.id} · ${v.name}</b><span>${v.kind==='equipment'?'Statybinė technika':`${v.payload} t · platforma ${v.length} × ${v.width} m · ${v.crane?'kranas iki '+v.lift+' t / siekis iki '+v.reach+' m':'be krano'} · priekaba ${v.trailer?'galima':'ne'}`}</span></div><small>${reasons.length?esc(reasons.join(' · ')):c?'Užimta: '+esc(c.id)+' ('+c.start+'–'+c.end+')':'Laisva pasirinktu laiku · reikia techninio patvirtinimo'}</small></button>`).join('')||'<div class="empty">Laisvos tinkamos technikos nerasta.<br>Pakeiskite vairuotoją arba užsakymo laiką.</div>'}</div><form id="assignmentForm"><div class="notice"><b>Techninį tinkamumą patvirtina žmogus</b>Rodoma preliminari atranka pagal demonstracinius parametrus. Kėlimo galios diagramą konkrečiu siekiu, krovinio aukštį, išdėstymą, tvirtinimą ir objekto sąlygas būtina įvertinti atskirai.</div><div class="checks">${check('Patvirtinu techninį suderinimą su atsakingu asmeniu','reviewed',false)}</div>${field('Suderinęs asmuo *','reviewedBy','','text','required maxlength="100"')}<div class="checks">${check('Pritaikyti pasirinktos technikos demo tarifus','applyRates',true)}</div><div id="assignError" role="alert"></div><div class="step-actions"><button type="submit" class="btn primary">Priskirti transportą ir vairuotoją</button><button type="button" class="btn secondary" id="editAssignment">Keisti užsakymo duomenis</button></div></form></div>`}
function draw(){openDrawer('Transporto parinkimas',content(),o.id);document.querySelector('[name="assignDriver"]').onchange=e=>{chosenDriver=e.target.value;candidate='';draw()};document.querySelector('[name="onlyFit"]').onchange=e=>{onlyFit=e.target.checked;draw()};document.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=()=>{candidate=b.dataset.candidate;document.querySelectorAll('[data-candidate]').forEach(x=>x.classList.toggle('chosen',x.dataset.candidate===candidate))});document.getElementById('editAssignment').onclick=()=>edit(id);document.getElementById('assignmentForm').onsubmit=e=>{e.preventDefault();const f=e.target;if(!candidate){formError('Pasirinkite transporto priemonę.','assignError');return}const data={...o,vehicle:candidate,driver:chosenDriver,reviewed:f.elements.reviewed.checked,reviewedBy:f.elements.reviewedBy.value.trim()};const error=Model.validate(data,orders.filter(x=>x!==o),vehicles);if(error){formError(error,'assignError');return}if(f.elements.applyRates.checked){const v=vehicles.find(v=>v.id===candidate);data.rate=v.rate;data.hourRate=v.hourRate}orders[orders.indexOf(o)]=data;const saved=persist();closeDrawer();render();if(saved)toast('Transportas ir vairuotojas priskirti')};}draw();}
function progress(id){const o=orders.find(x=>x.id===id),next=Model.next(o);if(!next)return;if(!o.vehicle||!o.driver||!o.reviewed){toast('Reikia priskirto transporto, vairuotojo ir techninio suderinimo.');if(page!=='driver')assign(id);return}const conflict=Model.conflict(o,orders);if(conflict){toast('Užimtumo konfliktas su '+conflict.id+'. Patikrinkite dispečerio planą.');return}if(next==='Užbaigtas'){finish(id);return}o.status=next;o.history.push({status:next,at:new Date().toISOString(),by:page==='driver'?selectedDriver:'Dispečeris'});const saved=persist();const inDrawer=!document.getElementById('overlay').hidden;render();if(inDrawer)detail(id);if(saved)toast('Pažymėta: '+next)}
function finish(id){const o=orders.find(x=>x.id===id),started=[...o.history].reverse().find(h=>h.status==='Dirba objekte'),elapsed=started?Math.max(0,Model.round((Date.now()-new Date(started.at).getTime())/3600000)):null;openDrawer('Užbaigti '+id,`<form id="finishForm"><div class="form-body"><div class="detail-note"><b>${esc(o.from)} → ${esc(o.to)}</b><br>Planas: ${o.km} km · ${o.hours} val. · ${euro(Model.planned(o))}</div><p class="subtitle finish-intro">Patvirtinkite faktiškai nuvažiuotus kilometrus ir dirbtas valandas. Pagal juos bus apskaičiuota galutinė kaina.</p><div class="form-grid">${field('Faktiniai kilometrai *','actualKm',o.actualKm,'number','required min="0" step="0.01"')}${field('Faktinės darbo valandos *','actualHours',o.actualHours??(elapsed===null?o.hours===0?0:'':Math.min(24,elapsed)),'number','required min="0" max="24" step="0.01"')}</div>${elapsed!==null?`<p class="small">Nuo mygtuko „Pradėjau darbą“: ${elapsed} val. Patikrinkite, ar visas šis laikas apmokestinamas.</p>`:''}<div id="finishPrice"></div><div id="finishError" role="alert"></div></div><div class="form-actions"><button type="button" class="btn secondary" id="finishCancel">Grįžti</button><button type="submit" class="btn primary">Patvirtinti faktą ir užbaigti</button></div></form>`);const form=document.getElementById('finishForm'),read=()=>({...o,status:'Užbaigtas',actualKm:form.elements.actualKm.value===''?null:Number(form.elements.actualKm.value),actualHours:form.elements.actualHours.value===''?null:Number(form.elements.actualHours.value)}),preview=()=>document.getElementById('finishPrice').innerHTML=priceComparison(read());form.oninput=preview;preview();document.getElementById('finishCancel').onclick=()=>page==='driver'?closeDrawer():detail(id);form.onsubmit=e=>{e.preventDefault();const data=read();if(Model.actual(data)===null||data.actualKm<0||data.actualHours<0||data.actualHours>24){formError('Įveskite teisingą faktinį atstumą ir darbo valandas.','finishError');return}data.history=[...o.history,{status:'Užbaigtas',at:new Date().toISOString(),by:page==='driver'?selectedDriver:'Dispečeris'}];orders[orders.indexOf(o)]=data;const saved=persist();closeDrawer();render();if(saved)toast('Užsakymas užbaigtas. Galutinė kaina: '+euro(Model.actual(data)))};}
function exportCsv(){const cols=[['id','Užsakymo nr.'],['date','Data'],['start','Pradžia'],['end','Pabaiga'],['arrival','Atvykimas į objektą'],['client','Klientas'],['phone','Kliento telefonas'],['email','El. paštas'],['driver','Vairuotojas'],['vehicle','Transportas'],['from','Iš kur'],['fromAddress','Pakrovimo adresas'],['pickupContact','Pakrovimo kontaktas'],['pickupPhone','Pakrovimo telefonas'],['to','Į kur'],['toAddress','Objekto adresas'],['siteContact','Objekto kontaktas'],['sitePhone','Objekto telefonas'],['access','Privažiavimas'],['cargoType','Krovinio tipas'],['cargo','Krovinys'],['weight','Svoris t'],['quantity','Vienetai'],['length','Ilgis m'],['width','Plotis m'],['height','Aukštis m'],['liftWeight','Keliamo vieneto svoris t'],['reach','Reikalingas siekis m'],['loading','Pakrovimas'],['unloading','Iškrovimas'],['installation','Montavimas'],['trailerRequired','Priekaba'],['reviewedBy','Suderinęs asmuo'],['km','Planuoti km'],['actualKm','Faktiniai km'],['rate','EUR/km'],['hours','Planuotos val.'],['actualHours','Faktinės val.'],['hourRate','EUR/val.'],['planned','Planuota kaina'],['actual','Galutinė kaina'],['difference','Kainos pokytis'],['status','Būsena'],['notes','Pastabos']];const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const csv='\ufeff'+[cols.map(c=>safe(c[1])).join(';'),...filtered().map(o=>cols.map(([k])=>{let v=k==='planned'?Model.planned(o):k==='actual'?Model.actual(o):k==='difference'?(Model.actual(o)===null?'':Model.round(Model.actual(o)-Model.planned(o))):o[k];if(typeof v==='boolean')v=v?'Taip':'Ne';if(typeof v==='number')v=String(v).replace('.',',');return safe(v)}).join(';'))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Reisu_uzsakymai.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Užsakymų sąrašas eksportuotas')}
document.getElementById('close').onclick=closeDrawer;document.getElementById('overlay').onclick=e=>{if(e.target.id==='overlay')closeDrawer()};document.addEventListener('keydown',e=>{if(document.getElementById('overlay').hidden)return;if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const items=[...document.querySelectorAll('.drawer button,.drawer input,.drawer select,.drawer textarea,.drawer a')].filter(x=>!x.disabled&&x.offsetParent!==null),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});document.getElementById('reset').onclick=()=>{if(confirm('Atkurti pradinius demonstracinius duomenis? Vietiniai pakeitimai bus pašalinti.')){orders=seed();const saved=persist();render();if(saved)toast('Demo duomenys atkurti')}};render();if(migrationMessage)toast(migrationMessage);
